/* =========================================================
   くらしノート — 新しい絵（試作 30個）

   icon-system.js の語彙だけで描いた30個です。857個へ展開する前に、
   「この画風で本当に全部いけるか」を確かめるための代表選手を選んであります。

   なぜこの30個か
   --------------
   ・果物と野菜（有機的な形。輪郭線がいちばん効きにくい）
   ・白いもの（牛乳・卵・ティッシュ。旧版がカードに溶けていた組）
   ・洗剤・柔軟剤・シャンプー・食器用洗剤（同じ「ボトル」で、色違いにしては
     いけない4つ。ここが崩れたら仕組みが間違っている）
   ・刃物と機械（直線と金属。有機物と同じ線幅で成立するか）
   ・建物・乗り物・行動（新規300個側の代表。買うもの以外へ広がるか）

   キーは既存のものをそのまま使います（新規のものを除く）。旧版の絵は
   product-icons.js に残したまま、ここに同じキーがあればそちらが使われます。
   ========================================================= */
